/**
 * Check if a date string is valid in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (typeof text !== 'string') {
    return false;
  }

  const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
  if (!dateRegex.test(text)) {
    return false;
  }

  const date = new Date(text + 'T00:00:00Z');
  if (isNaN(date.getTime())) {
    return false;
  }

  return date.toISOString().split('T')[0] === text;
}

/**
 * Add days to a date string (in YYYY-MM-DD format, UTC).
 * @param {string} date Date in YYYY-MM-DD format
 * @param {number} days Number of days to add
 * @returns {string} New date in YYYY-MM-DD format
 */
export function addDays(date, days) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().split('T')[0];
}

/**
 * Calculate the number of days between two dates (b - a, in whole days, UTC).
 * @param {string} a Date in YYYY-MM-DD format
 * @param {string} b Date in YYYY-MM-DD format
 * @returns {number} Number of days (b minus a)
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be in YYYY-MM-DD format and be a valid date.',
  DISCOUNT_INVALID: 'Discount must be a number between 0 and 100.',
  LINE_NOT_FOUND: 'No line with that SKU on the invoice.',
  NOT_DRAFT: 'Only draft invoices can be modified.',
  NOT_ISSUED: 'Invoice must be issued to record a payment.',
  NO_LINES: 'An invoice must have at least one line item.',
  OVERPAYMENT: 'Payment exceeds the balance due.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}

