});

test('invoiceTotals with single line', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const result = invoiceTotals(invoice);
  assert.strictEqual(result.subtotal, 17000);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 17000);
});

test('invoiceTotals with multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 8500 },
      { qty: 1, unitPrice: 9500 },
      { qty: 3, unitPrice: 1000 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 2*8500 + 1*9500 + 3*1000 = 17000 + 9500 + 3000 = 29500
  assert.strictEqual(result.subtotal, 29500);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 29500);
});

test('invoiceTotals with empty lines array', () => {
  const invoice = { lines: [] };
  const result = invoiceTotals(invoice);
  assert.strictEqual(result.subtotal, 0);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 0);
});

test('invoiceTotals does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 2, unitPrice: 8500 }],
  };
  const invoiceCopy = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepStrictEqual(invoice, invoiceCopy);
});

test('invoiceTotals with large amounts', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 120000 },
      { qty: 5, unitPrice: 245000 },
    ],
  };
  const result = invoiceTotals(invoice);
  // 10*120000 + 5*245000 = 1200000 + 1225000 = 2425000
  assert.strictEqual(result.subtotal, 2425000);
  assert.strictEqual(result.vat, 0);
  assert.strictEqual(result.total, 2425000);
});

test('lineTotal does not mutate line', () => {
  const line = { qty: 2, unitPrice: 8500 };
  const lineCopy = JSON.parse(JSON.stringify(line));

  lineTotal(line);

  assert.deepStrictEqual(line, lineCopy);
});

test('addLine adds a new line to invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 1 });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines.length, 2);
  assert.strictEqual(result.value.lines[1].sku, 'DEV-HOUR');
  assert.strictEqual(result.value.lines[1].qty, 1);
  assert.strictEqual(result.value.lines[1].name, 'Development (hour)');
  assert.strictEqual(result.value.lines[1].unitPrice, 9500);
});

test('addLine increases qty when SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

  assert.strictEqual(result.ok, true);
  assert.strictEqual(result.value.lines.length, 1);
  assert.strictEqual(result.value.lines[0].sku, 'DES-HOUR');
  assert.strictEqual(result.value.lines[0].qty, 5);
});

test('addLine validates qty', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-12-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const cases = [0, -1, 1.5, -0.5, Infinity];

  for (const qty of cases) {
    const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty });
    assert.strictEqual(result.ok, false);
    assert.strictEqual(result.error, 'QTY_INVALID');
  }
});

