test('lineVat without vatRate defaults to 0', () => {
  const line = { qty: 5, unitPrice: 1000 };
  assert.strictEqual(lineVat(line), 0);
});

test('lineVat with 0% VAT', () => {
  const line = { qty: 5, unitPrice: 1000, vatRate: 0 };
  assert.strictEqual(lineVat(line), 0);
});

test('lineVat with 9% VAT', () => {
  const line = { qty: 5, unitPrice: 1000, vatRate: 9 };
  // 5000 * 0.09 = 450
  assert.strictEqual(lineVat(line), 450);
});

test('lineVat with 21% VAT', () => {
  const line = { qty: 5, unitPrice: 1000, vatRate: 21 };
  // 5000 * 0.21 = 1050
  assert.strictEqual(lineVat(line), 1050);
});

test('lineVat calculated on amount after discount', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Subtotal: 5000
  // Discount: 500
  // After discount: 4500
  // VAT: 4500 * 0.21 = 945
  assert.strictEqual(lineVat(line), 945);
});

test('lineVat with 100% discount and VAT results in 0', () => {
  const line = { qty: 5, unitPrice: 1000, discountPercent: 100, vatRate: 21 };
  // After discount: 0
  // VAT: 0 * 0.21 = 0
  assert.strictEqual(lineVat(line), 0);
});

test('lineVat rounds to nearest cent', () => {
  const line = { qty: 3, unitPrice: 333, vatRate: 21 };
  // Subtotal: 999
  // VAT: 999 * 0.21 = 209.79 → rounds to 210
  assert.strictEqual(lineVat(line), 210);
});

